// Extract YouTube URLs from request
const youtubeUrls = items[0].json.urls || [];
const notebookId = items[0].json.notebook_id;

if (!youtubeUrls.length) {
  throw new Error('No YouTube URLs provided');
}

return youtubeUrls.map(url => ({
  json: {
    youtube_url: url,
    notebook_id: notebookId,
    timestamp: new Date().toISOString(),
    status: 'pending_extraction'
  }
}));

// Extract video metadata from YouTube page
const html = items[0].binary.data;

// In real implementation, parse HTML to extract:
// - Video title
// - Channel name
// - Video description
// - Publish date
// - Duration
// - View count

const metadata = {
  video_id: items[0].json.youtube_url,
  title: 'Extracted Title',  // Parse from HTML
  channel: 'Channel Name',   // Parse from HTML
  description: 'Video description...',  // Parse from HTML
  published_date: '2024-01-01',
  duration: '15:30',
  view_count: 10000,
  extraction_timestamp: new Date().toISOString()
};

return [{
  json: {
    ...items[0].json,
    metadata: metadata,
    status: 'metadata_extracted'
  }
}];

// Store video metadata in database
const metadata = items[0].json.metadata;
const notebookId = items[0].json.notebook_id;

// Database insert (MongoDB example)
const record = {
  notebook_id: notebookId,
  video_metadata: metadata,
  status: 'ready_for_notebooklm',
  created_at: new Date().toISOString(),
  processed: false
};

return [{
  json: {
    ...items[0].json,
    database_record: record,
    status: 'stored',
    message: 'Video metadata stored. Ready for NotebookLM import.'
  }
}];

// Manual step notification
// In actual workflow, this would trigger:
// 1. Notification to user to use Grabbit extension
// 2. Copy URLs to clipboard for NotebookLM Web Sync
// 3. Instructions for importing to NotebookLM

const instructions = {
  step_1: 'Use Grabbit Chrome extension to collect video URLs',
  step_2: 'Open NotebookLM and navigate to notebook: ' + items[0].json.notebook_id,
  step_3: 'Use NotebookLM Web Sync extension to import content',
  step_4: 'Wait for NotebookLM to process the content',
  step_5: 'Webhook will be called when ready for content generation'
};

return [{
  json: {
    ...items[0].json,
    instructions: instructions,
    next_webhook: '/notebooklm-ready',
    status: 'awaiting_manual_import'
  }
}];
